window.SBL_LESSONS.GR01 = {
  id: 'GR01',
  topicNumber: 1,
  topicTitle: 'Geopolitical and economic risks',
  title: 'Threats to individuals and businesses',
  href: '/geography/paper-2/hl-3/t1-geopolitical/l1-threats-to',
  syllabusFocus: 'Threats to individuals and businesses from hacking, identity theft and the implications of surveillance for personal freedoms; and the political, economic and physical risks to global supply chain flows, illustrated using the global oil supply chain.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is hacking?', request: 'Explain what hacking is and why it is a growing threat' },
    { label: 'Identity theft explained', request: 'Explain what identity theft is' },
    { label: 'Surveillance and personal freedom', request: 'Explain the implications of surveillance for personal freedoms' },
    { label: 'What is a supply chain?', request: 'Explain what a global supply chain is' },
    { label: 'Political risks to the oil supply chain', request: 'Explain political risks to the global oil supply chain' },
    { label: 'Economic risks to the oil supply chain', request: 'Explain economic risks to the global oil supply chain' },
    { label: 'Physical risks to the oil supply chain', request: 'Explain physical risks to the global oil supply chain' }
  ],
  checklist: [
    'I can define hacking.',
    'I can define identity theft.',
    'I can explain the implications of surveillance for personal freedom.',
    'I can define a global supply chain.',
    'I can explain political risks to supply chains.',
    'I can explain economic risks to supply chains.',
    'I can explain physical risks to supply chains.',
    'I can apply supply chain risk concepts using the global oil example.'
  ],
  readinessQuestions: [
    'What is the difference between hacking and identity theft?',
    'Explain one implication of mass surveillance for personal freedoms.',
    'What is meant by a "global supply chain"?',
    'Give one political risk and one physical risk to the global oil supply chain.',
    'Why might increasing global interconnection make hacking a growing threat?'
  ],
  quiz: [
    { q: 'Hacking is best defined as:', options: ['Any use of a computer for work purposes', 'Gaining unauthorised access to computer systems, networks or data', 'A type of legal cybersecurity audit', 'A method of encrypting personal data for protection'], correct: 1, explain: 'Hacking refers to gaining unauthorised access to computer systems, networks or data, often to steal information, disrupt services, or cause damage.', misconception: 'Hacking is sometimes assumed to always involve dramatic, visible disruption; much hacking is quiet and designed specifically to avoid detection while data is extracted.', tag: 'What is hacking?' },
    { q: 'Identity theft refers to:', options: ['Legally changing your name', 'Illegally obtaining and using someone else\u2019s personal information, typically for financial fraud', 'A government programme to issue new ID cards', 'A backup copy of personal documents'], correct: 1, explain: 'Identity theft involves illegally obtaining someone\u2019s personal information (such as bank details or ID numbers) and using it, typically to commit financial fraud in that person\u2019s name.', misconception: 'Identity theft is sometimes assumed to only involve stolen passwords; it more broadly covers any personal information used to impersonate someone for fraudulent gain.', tag: 'Identity theft explained' },
    { q: 'A key implication of mass surveillance for personal freedoms is that it can:', options: ['Have no effect on individual behaviour or privacy', 'Create a "chilling effect", where people alter their behaviour simply because they know they might be watched', 'Guarantee complete protection from all forms of crime', 'Only affect people who have committed a crime'], correct: 1, explain: 'A well-documented implication of surveillance is the "chilling effect" — people may self-censor or alter their behaviour simply because they are aware they could be monitored, even without direct evidence of wrongdoing.', misconception: 'Surveillance concerns are sometimes dismissed with "if you have nothing to hide, you have nothing to fear"; geographers and civil liberties scholars point to the chilling effect as a real, measurable impact on behaviour and freedom regardless of guilt or innocence.', tag: 'Surveillance and personal freedom' },
    { q: 'A global supply chain refers to:', options: ['A single factory producing all components of a product', 'The full network of processes, locations and organisations involved in moving a product from raw material to final consumer, often spanning multiple countries', 'A term used only for food products', 'A domestic transport system with no international element'], correct: 1, explain: 'A global supply chain is the full network of extraction, production, processing, transport and distribution stages that move a product from raw material to final consumer, often spanning many countries.', misconception: 'Supply chains are sometimes imagined as simple, single-country processes; in reality most modern supply chains, including oil, are highly globalised and multi-stage.', tag: 'What is a supply chain?' },
    { q: 'A political risk to the global oil supply chain would be:', options: ['A container ship running aground', 'Conflict, embargo or political instability in a major oil-producing or transit region disrupting supply', 'A change in consumer taste for a different fuel type', 'Routine scheduled maintenance at a refinery'], correct: 1, explain: 'Political risks to the oil supply chain include conflict, sanctions, embargoes or instability in key producing or transit regions, which can disrupt the flow of oil and cause significant knock-on effects globally.', misconception: 'Supply chain risks are sometimes assumed to be purely technical or physical; political decisions and instability are just as significant a risk category, particularly for a strategically important resource like oil.', tag: 'Political risks to the oil supply chain' },
    { q: 'An economic risk to the global oil supply chain would be:', options: ['A pipeline being physically damaged by a storm', 'Sudden price volatility disrupting the economies of countries heavily dependent on stable oil prices', 'A change in international shipping law', 'A country discovering a new small oil field'], correct: 1, explain: 'Sudden and significant price volatility is a major economic risk within the oil supply chain, as it can severely disrupt the economies of countries that are heavily dependent on stable oil import or export revenues.', misconception: 'Economic risk in a supply chain context is sometimes confused with physical risk; economic risk specifically concerns financial and market instability rather than physical infrastructure damage.', tag: 'Economic risks to the oil supply chain' },
    { q: 'A physical risk to the global oil supply chain would be:', options: ['A change in a country\u2019s corporate tax rate', 'Damage to pipelines, tankers or port infrastructure through accidents, piracy or attacks', 'A shift in global consumer demand patterns', 'A new international trade agreement'], correct: 1, explain: 'Physical risks to the oil supply chain include damage to critical infrastructure such as pipelines, oil tankers or ports, whether through accidents, piracy, extreme weather or deliberate attacks.', misconception: 'Physical risk is sometimes narrowly thought of as only natural disasters; deliberate human actions such as piracy or infrastructure attacks are equally significant physical risks in this context.', tag: 'Physical risks to the oil supply chain' },
    { q: 'Strategic geographic "chokepoints" (narrow, critical passage routes) are especially significant to the oil supply chain because:', options: ['They have no real strategic importance', 'A large proportion of global oil shipments may pass through a small number of narrow routes, making disruption there especially impactful', 'Oil is never transported by sea', 'They only affect a single country\u2019s domestic supply'], correct: 1, explain: 'Because a very large share of globally traded oil passes through a small number of narrow maritime chokepoints, disruption at any one of these points can have disproportionately large global consequences compared to disruption elsewhere in the supply chain.', misconception: 'It is sometimes assumed all points along a supply chain carry equal risk; geographic chokepoints concentrate risk because so much global flow depends on a small number of critical routes.', tag: 'Political risks to the oil supply chain' },
    { q: 'The increasing digital interconnection of businesses and individuals has made hacking a growing threat mainly because:', options: ['Fewer systems are now connected to the internet than in the past', 'More systems, devices and personal data are now connected and accessible online, creating more potential points of entry for attackers', 'Hacking has become technically impossible with modern security', 'Businesses no longer store any sensitive data digitally'], correct: 1, explain: 'As more devices, systems and personal data become connected online (sometimes called an expanding "attack surface"), there are simply more potential entry points for hackers to exploit, making cybersecurity an increasingly significant global risk.', misconception: 'Growing digital connectivity is often framed only in terms of its benefits (efficiency, communication); it also creates a corresponding growth in genuine security vulnerability that geographers studying global risk need to account for.', tag: 'What is hacking?' },
    { q: 'Overall, threats such as hacking, identity theft and supply chain disruption illustrate that increased global interconnection:', options: ['Brings only benefits, with no accompanying risks', 'Creates genuine new vulnerabilities and risks for individuals, businesses and governments, alongside its benefits', 'Has no real link to geography as a subject', 'Only affects wealthy countries and individuals'], correct: 1, explain: 'This lesson demonstrates a recurring theme in this unit: increased global interconnection (digital, economic and physical) brings genuine benefits but also creates new vulnerabilities and risks for individuals, businesses and governments alike.', misconception: 'Globalisation is sometimes discussed only in terms of its opportunities; this unit specifically examines the flip side — the new risks that come hand-in-hand with greater global connection.', tag: 'What is a supply chain?' }
  ]
};

window.SBL_LESSONS.GR02 = {
  id: 'GR02',
  topicNumber: 1,
  topicTitle: 'Geopolitical and economic risks',
  title: 'Emerging threats to political and economic sovereignty',
  href: '/geography/paper-2/hl-3/t1-geopolitical/l2-emerging',
  syllabusFocus: 'New and emerging threats to the political and economic sovereignty of states, including profit repatriation and tax avoidance by transnational corporations (TNCs) and wealthy individuals, and disruptive technological innovations such as drones and 3D printing.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is sovereignty?', request: 'Explain what political and economic sovereignty means for a state' },
    { label: 'Profit repatriation explained', request: 'Explain what profit repatriation is' },
    { label: 'Tax avoidance by TNCs', request: 'Explain how TNCs can legally avoid tax' },
    { label: 'The Apple-Ireland example', request: 'Explain the Apple and Ireland tax example' },
    { label: 'Drones as a sovereignty threat', request: 'Explain how drones can threaten state sovereignty' },
    { label: '3D printing as a sovereignty threat', request: 'Explain how 3D printing can threaten state sovereignty' },
    { label: 'How new technology challenges government control', request: 'Explain the broader challenge new technology poses to government control' }
  ],
  checklist: [
    'I can define political and economic sovereignty.',
    'I can explain profit repatriation.',
    'I can explain how TNCs use tax avoidance strategies.',
    'I can apply the Apple-Ireland case to explain tax avoidance.',
    'I can explain how drones threaten state sovereignty.',
    'I can explain how 3D printing threatens state sovereignty.',
    'I can evaluate the overall impact of new technology on sovereignty.'
  ],
  readinessQuestions: [
    'What is meant by a state\u2019s political and economic sovereignty?',
    'Explain what profit repatriation means.',
    'Why might a TNC choose to route profits through a country with low corporate tax rates?',
    'Give one way drones can challenge state sovereignty.',
    'Give one way 3D printing can challenge state sovereignty.'
  ],
  quiz: [
    { q: 'A state\u2019s political and economic sovereignty refers to:', options: ['Its total population size', 'Its authority to govern itself and control its own political and economic affairs without external interference', 'The number of trade agreements it has signed', 'Its physical land area'], correct: 1, explain: 'Sovereignty refers to a state\u2019s authority to govern itself and control its own political and economic affairs independently, without undue external interference.', misconception: 'Sovereignty is sometimes confused with simple size or wealth; it specifically concerns a state\u2019s independent authority and control, which can be challenged regardless of the state\u2019s size.', tag: 'What is sovereignty?' },
    { q: 'Profit repatriation refers to:', options: ['A company permanently closing its overseas operations', 'The process of transferring profits earned in a foreign country back to a company\u2019s home country or a chosen low-tax location', 'A government policy limiting foreign investment', 'The process of a country repaying international debt'], correct: 1, explain: 'Profit repatriation is the process by which a company transfers profits earned in one country (often through a foreign subsidiary) back to its home country or to another jurisdiction it has chosen, often for tax reasons.', misconception: 'Profit repatriation is sometimes assumed to be inherently illegal; the underlying transfer of profits is often legal, though the specific structures used to minimise tax in the process can be controversial.', tag: 'Profit repatriation explained' },
    { q: 'Tax avoidance, as distinct from tax evasion, refers to:', options: ['Illegally hiding income from tax authorities', 'Legally minimising the amount of tax owed by exploiting loopholes or favourable rules in tax law', 'Refusing to pay any tax under any circumstances', 'A tax that only applies to individuals, never companies'], correct: 1, explain: 'Tax avoidance involves legally minimising tax liability by making use of loopholes, exemptions or favourable structures within existing tax law, distinct from tax evasion, which is the illegal non-payment or under-payment of tax owed.', misconception: 'Tax avoidance and tax evasion are often used interchangeably in everyday speech; the key distinction for geographers and economists is that avoidance is legal (even if controversial), while evasion is illegal.', tag: 'Tax avoidance by TNCs' },
    { q: 'TNCs sometimes route significant profits through countries such as Ireland mainly because:', options: ['Ireland has no relevant infrastructure for business', 'Ireland has historically offered a relatively low corporate tax rate and favourable rules that make it attractive for structuring international profits', 'It is a legal requirement to route all European profits through Ireland', 'Ireland has the largest consumer market in Europe'], correct: 1, explain: 'Countries such as Ireland have historically offered comparatively low corporate tax rates and rules that make them attractive locations for TNCs to legally structure and route significant shares of their international profits, reducing their overall global tax bill.', misconception: 'It is sometimes assumed profits are routed to a country based on where products are actually sold or made; in practice, profit routing decisions are often driven primarily by tax structuring considerations, separate from where economic activity actually occurs.', tag: 'The Apple-Ireland example' },
    { q: 'A consequence of large-scale corporate tax avoidance for a state\u2019s sovereignty is that it can:', options: ['Have no effect on government revenue or capacity', 'Reduce government tax revenue, potentially limiting a state\u2019s ability to fund public services and exercise full economic control', 'Automatically increase a state\u2019s political influence globally', 'Guarantee improved public services in every country involved'], correct: 1, explain: 'Large-scale tax avoidance by TNCs can significantly reduce the tax revenue collected by governments, potentially limiting their capacity to fund public services and reducing their effective economic control — a genuine erosion of economic sovereignty.', misconception: 'Tax avoidance is sometimes seen as a purely financial/business issue, when geographers frame it specifically as a sovereignty issue: it constrains what a democratically elected government can actually do with its own economy.', tag: 'The Apple-Ireland example' },
    { q: 'Drones present a challenge to state sovereignty mainly because they can:', options: ['Only be used within a single country\u2019s own airspace', 'Cross borders and conduct surveillance or attacks with reduced risk of detection or accountability, challenging a state\u2019s control over its own airspace and security', 'Be easily and reliably detected and stopped by every state', 'Only be operated by national governments'], correct: 1, explain: 'Drones can potentially cross international borders and conduct surveillance or attacks with reduced risk of detection, challenging a state\u2019s traditional control over its own airspace, security and accountability for cross-border incidents.', misconception: 'New military and surveillance technology is sometimes assumed to only affect large-scale conventional warfare; drones specifically challenge sovereignty because of how they can bypass traditional, visible forms of border control and military engagement.', tag: 'Drones as a sovereignty threat' },
    { q: '3D printing presents a challenge to state sovereignty mainly because it can:', options: ['Only be used to produce toys and small household items', 'Enable local, decentralised production of goods (including potentially weapons or restricted items), bypassing traditional trade regulation and state oversight of manufacturing', 'Only operate under strict government licensing in every country', 'Guarantee improved national security in every state'], correct: 1, explain: '3D printing enables decentralised, local production of items, potentially including restricted or dangerous items, which can bypass traditional trade regulation, customs controls and state oversight of manufacturing and distribution.', misconception: '3D printing is sometimes seen only as a manufacturing efficiency technology; its sovereignty implications specifically relate to how it can circumvent state control over what is produced and where.', tag: '3D printing as a sovereignty threat' },
    { q: 'A common theme linking tax avoidance, drones and 3D printing as sovereignty threats is that they all:', options: ['Require direct government approval before they can be used', 'Allow non-state actors (companies, individuals, or others) to bypass traditional forms of state control and regulation', 'Have no real connection to state authority or control', 'Only affect very small, low-income countries'], correct: 1, explain: 'A common thread across these examples is that new technologies and financial structures increasingly allow non-state actors — companies, wealthy individuals, or others — to bypass traditional forms of state regulation and control, challenging sovereignty in new and evolving ways.', misconception: 'These examples might initially seem unrelated (finance versus technology), but geographers group them together because they share the same underlying theme: eroding a state\u2019s traditional capacity for control.', tag: 'How new technology challenges government control' },
    { q: 'A key difficulty for governments in responding to these emerging threats to sovereignty is that:', options: ['These technologies and financial flows are entirely contained within national borders and easy to regulate', 'These threats often operate across borders and evolve faster than national regulation and international cooperation can keep pace with', 'Governments have unlimited legal power to stop any of these activities immediately', 'These threats have existed unchanged for centuries with no need for new responses'], correct: 1, explain: 'A significant challenge is that these threats — whether financial flows, drone technology or 3D printing — often operate across national borders and evolve rapidly, frequently outpacing the ability of national regulation and international cooperation to respond effectively.', misconception: 'It is sometimes assumed governments can simply legislate these issues away quickly; the cross-border and fast-evolving nature of these threats makes coordinated, effective regulation genuinely difficult.', tag: 'How new technology challenges government control' },
    { q: 'Overall, this lesson demonstrates that globalization and new technology can threaten state sovereignty by:', options: ['Having no real effect on how states function', 'Creating new pathways for capital, goods and technology to move in ways that bypass traditional state control and oversight', 'Strengthening every state\u2019s control over its economy and territory equally', 'Only affecting sovereignty in a positive, strengthening way'], correct: 1, explain: 'This lesson demonstrates that globalization and new technology create new pathways for capital, goods, and activity to move and operate in ways that can bypass traditional state control, oversight and regulation, representing a genuine emerging challenge to political and economic sovereignty.', misconception: 'Globalization\u2019s effect on sovereignty is sometimes assumed to be neutral or purely positive (increased trade, cooperation); this lesson highlights the more complex reality that it can simultaneously create genuine new vulnerabilities for state control.', tag: 'What is sovereignty?' }
  ]
};

window.SBL_LESSONS.GR03 = {
  id: 'GR03',
  topicNumber: 1,
  topicTitle: 'Geopolitical and economic risks',
  title: 'The link between globalization and increased nationalism',
  href: '/geography/paper-2/hl-3/t1-geopolitical/l3-the-link',
  syllabusFocus: 'The correlation between increased globalization and renewed nationalism/tribalization, illustrated using two detailed examples of geopolitical tension and conflict.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is nationalism?', request: 'Explain what nationalism means in a geopolitical context' },
    { label: 'What is tribalization?', request: 'Explain what tribalization means' },
    { label: 'Why globalization can trigger a nationalist backlash', request: 'Explain why globalization can provoke a nationalist backlash in some places' },
    { label: 'Example: increasing isolationism', request: 'Explain what is meant by a country becoming more isolationist on the world stage' },
    { label: 'Example: Yemen', request: 'Explain how global and regional geopolitical rivalries have contributed to tensions in Yemen' },
    { label: 'Comparing the two examples', request: 'Compare these two examples of geopolitical tension linked to globalization and nationalism' }
  ],
  checklist: [
    'I can define nationalism.',
    'I can define tribalization.',
    'I can explain why globalization can provoke a nationalist backlash.',
    'I can explain an example of increasing isolationism on the world stage.',
    'I can explain how global/regional rivalries have contributed to tension in Yemen.',
    'I can compare these two examples.',
    'I can evaluate the correlation between globalization and nationalism.'
  ],
  readinessQuestions: [
    'What is the difference between nationalism and tribalization?',
    'Give one reason globalization can provoke a nationalist backlash in some places.',
    'Explain what is meant by a country becoming more "isolationist".',
    'Explain how external, global powers have been connected to tensions within Yemen.',
    'Is the relationship between globalization and nationalism best described as correlation or proven causation? Explain your answer.'
  ],
  quiz: [
    { q: 'Nationalism, in a geopolitical context, refers to:', options: ['A belief that all countries should have identical political systems', 'A strong sense of identity, loyalty and pride centred on one\u2019s own nation, often prioritising national interests', 'A term used only to describe international cooperation', 'A policy of unrestricted global trade'], correct: 1, explain: 'Nationalism refers to a strong sense of identity, loyalty and pride centred on one\u2019s own nation, which often involves prioritising national interests, culture and sovereignty, sometimes in tension with international cooperation.', misconception: 'Nationalism is sometimes assumed to be identical to patriotism in all cases; while related, nationalism specifically implies prioritising national interest, sometimes above international cooperation or other groups\u2019 interests.', tag: 'What is nationalism?' },
    { q: 'Tribalization refers to:', options: ['The process of countries joining together into larger political unions', 'A fragmentation of identity into smaller groups based on characteristics such as ethnicity, culture or region, rather than a broader national or global identity', 'A term describing increased international trade', 'A synonym for globalization'], correct: 1, explain: 'Tribalization describes a process where identity fragments into smaller groups, often based on ethnicity, culture, religion or region, rather than uniting around a broader national or global identity.', misconception: 'Tribalization is sometimes confused with nationalism; while related, tribalization specifically implies fragmentation into smaller sub-national groups, whereas nationalism centres on the nation as a whole.', tag: 'What is tribalization?' },
    { q: 'A commonly cited reason globalization can provoke a nationalist backlash in some places is that:', options: ['Globalization\u2019s benefits and costs are always distributed perfectly evenly within every country', 'Some communities perceive job losses, cultural change, or reduced control over local decisions as a direct result of increased global economic integration', 'Globalization has no measurable economic or cultural effects on any community', 'Nationalist movements have no connection to economic change'], correct: 1, explain: 'A commonly cited driver of nationalist backlash is that some communities perceive job losses, rapid cultural change, or a loss of local control as directly linked to increased global economic integration, generating resentment towards globalization and its institutions.', misconception: 'Globalization is sometimes assumed to benefit everyone equally within a country; in reality its costs and benefits are often unevenly distributed, which can fuel political backlash in the communities that feel most negatively affected.', tag: 'Why globalization can trigger a nationalist backlash' },
    { q: 'A country adopting a more "isolationist" foreign policy stance generally means it:', options: ['Increases its involvement in international organisations and agreements', 'Reduces its participation in international agreements, organisations or alliances, prioritising national interests and independence over international cooperation', 'Has no foreign policy of any kind', 'Only applies to very small countries with limited global influence'], correct: 1, explain: 'An isolationist stance generally involves a country reducing its participation in international agreements, organisations or alliances, and prioritising national interests and independent decision-making over deeper international cooperation.', misconception: 'Isolationism is sometimes assumed to mean a country has no interaction with the rest of the world at all; in practice it more specifically refers to a reduced preference for binding international cooperation and institutions.', tag: 'Example: increasing isolationism' },
    { q: 'Geopolitical tensions in Yemen have been significantly shaped by:', options: ['A conflict entirely isolated from any regional or global influence', 'A combination of internal political divisions and involvement or influence from external regional and global powers pursuing their own strategic interests', 'A dispute with no connection to any wider geopolitical rivalry', 'A purely economic disagreement with no political dimension'], correct: 1, explain: 'Tensions and conflict in Yemen have been shaped by a combination of internal political divisions and the involvement of external regional and global powers, each pursuing their own strategic interests in the wider region — illustrating how local conflicts can become entangled with broader geopolitical rivalries.', misconception: 'Complex regional conflicts are sometimes explained using only a single cause; geographers emphasise that conflicts like Yemen\u2019s typically involve an interaction between internal divisions and external geopolitical interests.', tag: 'Example: Yemen' },
    { q: 'Yemen illustrates a broader pattern relevant to this lesson because it shows how:', options: ['Internal conflicts never have any connection to global interactions', 'A local or national-scale conflict can become entangled with wider global and regional geopolitical rivalries', 'Global powers never have any interest in smaller or less economically powerful states', 'Conflict only ever occurs in economically wealthy regions'], correct: 1, explain: 'Yemen illustrates how a conflict originating from internal, national-scale divisions can become entangled with wider regional and global geopolitical rivalries, as external powers pursue their own strategic interests within the conflict — directly relevant to this lesson\u2019s theme of global interaction creating geopolitical risk.', misconception: 'It is sometimes assumed that global geopolitical interest is limited to powerful or wealthy states; external powers can and do become significantly involved in the affairs of less economically powerful states when strategic interests are at stake.', tag: 'Example: Yemen' },
    { q: 'Comparing an example of a country becoming more isolationist with the example of tensions in Yemen shows two different but related aspects of this lesson\u2019s theme, namely:', options: ['These two examples have no meaningful connection to one another', 'One example shows a state actively reducing its global engagement, while the other shows how global/regional rivalries can become entangled with a more local conflict — together illustrating different geopolitical responses to global interconnection', 'Both examples show identical processes with no meaningful differences', 'Neither example has any real connection to globalization'], correct: 1, explain: 'These two examples illustrate different but related geopolitical responses to global interconnection: one shows a state deliberately reducing its global engagement (isolationism), while the other shows how global and regional rivalries can become entangled within a more localised conflict — together demonstrating the varied ways globalization and geopolitical tension interact.', misconception: 'Comparative case studies are sometimes treated as two separate, disconnected examples to memorise, when a stronger answer explicitly compares what they reveal about the shared underlying theme.', tag: 'Comparing the two examples' },
    { q: 'When geographers describe a "correlation" between increased globalization and renewed nationalism, this means:', options: ['Globalization has been definitively proven to be the sole direct cause of all nationalism everywhere', 'The two trends have tended to occur together in various contexts, without necessarily proving that one directly and solely causes the other', 'There is no observable relationship between the two trends at all', 'Nationalism only ever occurs in the complete absence of globalization'], correct: 1, explain: 'Describing a "correlation" means the two trends have tended to occur together in various contexts, without necessarily proving that globalization is the sole, direct cause of nationalism in every case — other factors (economic, cultural, historical) are also typically involved.', misconception: 'Correlation is sometimes mistakenly treated as proof of direct causation; a stronger geographical answer explicitly distinguishes between an observed relationship (correlation) and a definitively proven single cause (causation).', tag: 'Why globalization can trigger a nationalist backlash' },
    { q: 'A geographically balanced view of the relationship between globalization and nationalism would recognise that:', options: ['Globalization and nationalism are always completely incompatible with no possible coexistence', 'Global interdependence and nationalist or tribalist responses can coexist in tension, with different groups and places responding differently to the same global processes', 'Nationalism has completely disappeared everywhere due to globalization', 'Every country responds to globalization in an identical way'], correct: 1, explain: 'A balanced geographical view recognises that global interdependence and nationalist or tribalist responses can coexist in genuine tension, with different places, groups and political movements responding very differently to the same underlying global processes.', misconception: 'It is tempting to frame globalization and nationalism as a simple either/or binary; geographers instead emphasise the more nuanced reality of ongoing tension and varied responses across different places.', tag: 'Comparing the two examples' },
    { q: 'Overall, this lesson connects to the wider theme of this unit by showing that:', options: ['Global interaction and connection only ever produce cooperation, with no associated tension or risk', 'Increased global interaction can itself become a source of geopolitical risk, as it provokes varied and sometimes conflicting political responses in different places', 'Nationalism and geopolitical conflict are entirely unrelated to the study of global risks', 'This topic has no connection to any other part of this unit'], correct: 1, explain: 'This lesson reinforces this unit\u2019s wider theme: increased global interaction does not only bring cooperation and opportunity, but can itself become a source of genuine geopolitical risk, as it provokes varied, and sometimes conflicting, political responses in different places around the world.', misconception: 'This lesson can seem disconnected from the more technical/economic risks studied earlier in the topic (hacking, sovereignty); it is actually a natural extension of the same theme — global interconnection creating new forms of risk and tension.', tag: 'Why globalization can trigger a nationalist backlash' }
  ]
};

